"use client"

import "maplibre-gl/dist/maplibre-gl.css"

import { MapIcon } from "lucide-react"
import { useTheme } from "next-themes"
import { forwardRef, useState } from "react"
import Map, { AttributionControl, NavigationControl, type MapProps, type MapRef } from "react-map-gl/maplibre"

import { cn } from "@/lib/utils"

// Generated by scripts/map-style/build.mjs from OpenFreeMap's Liberty style (plans/08 §0).
const STYLES = { light: "/map/light.json", dark: "/map/dark.json" } as const

/** Ho Chi Minh City: where the map opens when there is nothing to fit. */
export const DEFAULT_VIEW = { longitude: 106.7009, latitude: 10.7769, zoom: 12 }

function hasWebGL() {
  try {
    const canvas = document.createElement("canvas")
    return !!(canvas.getContext("webgl2") ?? canvas.getContext("webgl"))
  } catch {
    return false
  }
}

/**
 * MapLibre map on our OpenStreetMap vector style, switching light/dark with the
 * app theme. Client-only (WebGL): import it through `next/dynamic` with
 * `ssr: false`, so MapLibre stays out of every other page's bundle.
 */
export const BaseMap = forwardRef<MapRef, Omit<MapProps, "mapStyle"> & { className?: string }>(
  function BaseMap({ className, children, onLoad, ...props }, ref) {
    const { resolvedTheme } = useTheme()
    const [webgl] = useState(hasWebGL)

    if (!webgl) {
      return (
        <div className={cn("bg-muted text-muted-foreground flex flex-col items-center justify-center gap-2 p-6 text-center text-sm", className)}>
          <MapIcon className="size-6" />
          Trình duyệt này không hỗ trợ WebGL nên không hiển thị được bản đồ.
        </div>
      )
    }

    return (
      <div className={cn("relative overflow-hidden", className)}>
        <Map
          ref={ref}
          initialViewState={DEFAULT_VIEW}
          mapStyle={STYLES[resolvedTheme === "dark" ? "dark" : "light"]}
          attributionControl={false}
          // Rotation by mouse is easy to trigger by accident; touch keeps two-finger rotate.
          dragRotate={false}
          maxZoom={19}
          style={{ width: "100%", height: "100%" }}
          onLoad={(e) => {
            // Compact attribution starts expanded and would cover a small map; start at its ⓘ.
            e.target.getContainer().querySelector(".maplibregl-ctrl-attrib")?.classList.remove("maplibregl-compact-show")
            onLoad?.(e)
          }}
          {...props}
        >
          <NavigationControl position="top-right" visualizePitch />
          {/* © OpenMapTiles © OpenStreetMap — required by the tile licence, comes from the style source. */}
          <AttributionControl position="bottom-right" compact />
          {children}
        </Map>
      </div>
    )
  },
)
